@@
 export const DEFAULT_JOB_OPTIONS = {
   attempts: 1,
 }
+
+const normalizeRedisClient = client => {
+  if (client && client.options) {
+    client.options.maxRetriesPerRequest = null
+    client.options.enableReadyCheck = false
+  }
+
+  return client
+}
+
+const resolveQueueOptions = options => {
+  if (typeof options.createClient !== 'function') {
+    return options
+  }
+
+  return {
+    ...options,
+    createClient: (type, redisOptions) => normalizeRedisClient(options.createClient(type, redisOptions)),
+  }
+}

 // createQueue :: (String, Object) -> Queue
-export default (redisDsn, options = {}) => new Bull('request-queue', redisDsn, { ...DEFAULT_QUEUE_OPTIONS, ...options })
+export default (redisDsn, options = {}) => new Bull('request-queue', redisDsn, resolveQueueOptions({
+  ...DEFAULT_QUEUE_OPTIONS,
+  ...options,
+}))
*** End Patch

